  function homeCompletedSeasonOnlyText(value) {
    const text = homeCompletedStem(value);
    return /^(?:season\s*\d{1,2}|s\d{1,2})(?:\s*\((?:season\s*|s)\d{1,2}\))?$/i.test(text)
