      state.selectedCompletedFinalTrustKey = selected.key || "";
      renderCompletedFinalTrust(state.lastCompletedPayload, state.lastCompletedRows, state.lastCompletedPendingProofRows, state.lastCompletedPendingPayload);
      return true;
    }

