// completed/filters.js
// Split child of completedView.js. Loaded before completedView.js; the parent
// consumes this temporary stash global and deletes it immediately.

(function () {
  "use strict";

  const COMPLETED_LIBRARY_UNKNOWN_VALUE = "__unknown__";

  function createCompletedFiltersModule({
    byId,
    completedCurrentRows,
    completedFilterFields,
    completedInvestigationFilterLabel,
    completedMatchesInvestigationFilter,
    completedMissingRows,
    completedReviewRows,
    completedReviewRowReasons,
    completedTableRowStatus,
    filterRows,
    filterRowsByInvestigation,
    filterRowsByStatus,
    renderCompletedRows,
    setText,
    state,
  } = {}) {
    completedCurrentRows = typeof completedCurrentRows === "function" ? completedCurrentRows : function (rows) { return Array.isArray(rows) ? rows : []; };
    completedFilterFields = Array.isArray(completedFilterFields) ? completedFilterFields : [];
    completedInvestigationFilterLabel = typeof completedInvestigationFilterLabel === "function" ? completedInvestigationFilterLabel : function () { return ""; };
    completedMatchesInvestigationFilter = typeof completedMatchesInvestigationFilter === "function" ? completedMatchesInvestigationFilter : function () { return true; };
    completedMissingRows = typeof completedMissingRows === "function" ? completedMissingRows : function (rows) {
      return (Array.isArray(rows) ? rows : []).filter((row) => row?.output_exists === false && !row?.promoted_cleaned);
    };
    completedReviewRows = typeof completedReviewRows === "function" ? completedReviewRows : function () { return []; };
    completedReviewRowReasons = typeof completedReviewRowReasons === "function" ? completedReviewRowReasons : function () { return []; };
    completedTableRowStatus = typeof completedTableRowStatus === "function" ? completedTableRowStatus : function () { return "normal"; };
    renderCompletedRows = typeof renderCompletedRows === "function" ? renderCompletedRows : function () {};
    setText = typeof setText === "function" ? setText : function () {};
    state = state && typeof state === "object" ? state : {};

    function completedNormalizeLibraryFilter(value) {
      return String(value || "all").trim().toLowerCase() || "all";
    }

    function completedLibraryProfile(item) {
      return item?.library_profile && typeof item.library_profile === "object" ? item.library_profile : {};
    }

    function completedLibraryKindLabel(value) {
      const raw = String(value || "").trim();
      const normalized = raw.toLowerCase();
      if (!normalized || ["all", "auto", "unknown", "n/a", "none", "null"].includes(normalized)) return "";
      if (["movie", "movies", "film", "films"].includes(normalized)) return "Movie";
      if (["tv", "episode", "episodes", "show", "shows", "series"].includes(normalized)) return "TV";
      return raw;
    }

    function completedLibraryKindCandidates(item) {
      const profile = completedLibraryProfile(item);
      return [
        item?.library_designation,
        profile.designation,
        item?.media_kind,
        item?.media_type,
        profile.media_kind,
        profile.media_type,
      ].map(completedLibraryKindLabel).filter(Boolean);
    }

    function completedLibraryTextCandidates(item) {
      const profile = completedLibraryProfile(item);
      return [
        item?.library_id,
        item?.library_name,
        profile.library_id,
        profile.id,
        profile.library_name,
        profile.name,
        ...completedLibraryKindCandidates(item),
        item?.library_source_root,
        item?.library_output_root,
        profile.source_root,
        profile.output_root,
      ].map((value) => String(value || "").trim()).filter(Boolean);
    }

    function completedLibraryOptionKey(item) {
      const candidate = completedLibraryTextCandidates(item)[0] || "";
      return candidate ? completedNormalizeLibraryFilter(candidate) : COMPLETED_LIBRARY_UNKNOWN_VALUE;
    }

    function completedLibraryDisplayLabel(item) {
      const profile = completedLibraryProfile(item);
      return [
        item?.library_name,
        profile.library_name,
        profile.name,
        item?.library_id,
        profile.library_id,
        profile.id,
        ...completedLibraryKindCandidates(item),
      ].map((value) => String(value || "").trim()).find(Boolean) || "Unknown library";
    }

    function completedLibraryOptions(rows) {
      const optionsByValue = new Map();
      (Array.isArray(rows) ? rows : []).forEach((row) => {
        const value = completedLibraryOptionKey(row);
        if (!optionsByValue.has(value)) {
          optionsByValue.set(value, {
            label: completedLibraryDisplayLabel(row),
            value,
          });
        }
      });
      return Array.from(optionsByValue.values()).sort((left, right) => {
        if (left.value === COMPLETED_LIBRARY_UNKNOWN_VALUE) return 1;
        if (right.value === COMPLETED_LIBRARY_UNKNOWN_VALUE) return -1;
        return left.label.localeCompare(right.label);
      });
    }

    function completedLibraryMatchesFilter(item, libraryFilter) {
      const normalized = completedNormalizeLibraryFilter(libraryFilter);
      if (!normalized || normalized === "all") return true;
      return completedLibraryOptionKey(item) === normalized;
    }

    function completedLibraryFilterLabel(libraryFilter) {
      const normalized = completedNormalizeLibraryFilter(libraryFilter);
      if (!normalized || normalized === "all") return "all libraries";
      const select = byId("completed-library-filter");
      const options = select ? Array.from(select.children || []) : [];
      const option = options.find((candidate) => completedNormalizeLibraryFilter(candidate?.value) === normalized);
      return String(option?.textContent || "").trim() || (normalized === COMPLETED_LIBRARY_UNKNOWN_VALUE ? "Unknown library" : normalized);
    }

    function syncCompletedLibraryFilterOptions(rows) {
      const select = byId("completed-library-filter");
      if (!select) return "all";
      const previousValue = completedNormalizeLibraryFilter(select.value);
      const doc = select.ownerDocument || document;
      const allOption = doc.createElement("option");
      allOption.value = "all";
      allOption.textContent = "All libraries";
      const options = completedLibraryOptions(rows).map((item) => {
        const option = doc.createElement("option");
        option.value = item.value;
        option.textContent = item.label;
        return option;
      });
      select.replaceChildren(allOption, ...options);
      const availableValues = new Set(["all", ...options.map((option) => completedNormalizeLibraryFilter(option.value))]);
      select.value = availableValues.has(previousValue) ? previousValue : "all";
      return completedNormalizeLibraryFilter(select.value);
    }

    function completedFilteredRows(baseRows, filterText, statusFilter, investigationFilter, libraryFilter) {
      const sourceRows = Array.isArray(baseRows) ? baseRows : [];
      const textRows = typeof filterRows === "function" ? filterRows(sourceRows, filterText, completedFilterFields) : sourceRows;
      const statusRows = typeof filterRowsByStatus === "function" ? filterRowsByStatus(textRows, statusFilter, completedDisplayRowStatus) : textRows;
      const investigationRows = typeof filterRowsByInvestigation === "function"
        ? filterRowsByInvestigation(statusRows, investigationFilter, completedMatchesInvestigationFilter)
        : statusRows;
      return investigationRows.filter((row) => completedLibraryMatchesFilter(row, libraryFilter));
    }

    function completedReviewReasonsForDisplay(item) {
      const reasons = completedReviewRowReasons(item);
      return Array.isArray(reasons) ? reasons.filter(Boolean) : [];
    }

    function completedDisplayRowStatus(item) {
      const status = String(completedTableRowStatus(item) || "normal").toLowerCase();
      const reasons = completedReviewReasonsForDisplay(item);
      if (item?.output_exists === false) return "blocked";
      if (["warning", "changed", "ready", "completed", "match", "normal"].includes(status) && !reasons.length) return "match";
      return status;
    }

    function completedReviewCount(payload, rows) {
      const reviewRows = completedReviewRows(payload || {}, Array.isArray(rows) ? rows : []);
      return Array.isArray(reviewRows) ? reviewRows.length : 0;
    }

    function completedRiskStatusLine(payload, rows) {
      const rowList = Array.isArray(rows) ? rows : [];
      const missingRows = completedMissingRows(rowList);
      const currentRows = completedCurrentRows(rowList);
      const missingCount = Array.isArray(missingRows) ? missingRows.length : 0;
      const reviewCount = completedReviewCount(payload, Array.isArray(currentRows) ? currentRows : []);
      if (missingCount > 0) return `${missingCount} missing from expected destination`;
      if (reviewCount > 0) return `${reviewCount} current output${reviewCount === 1 ? "" : "s"} need review`;
      return "No current output blockers";
    }

    function completedRowsStatusLine(visibleRows, renderedRows, totalRows, renderLimit) {
      if (visibleRows > renderLimit) {
        return `${renderedRows} shown / ${visibleRows} filtered / ${totalRows} rows`;
      }
      return `${visibleRows} / ${totalRows} row${totalRows === 1 ? "" : "s"}`;
    }

    function completedPublishReconciliationLoaded() {
      const payload = state.lastPublishReconciliationPayload && typeof state.lastPublishReconciliationPayload === "object"
        ? state.lastPublishReconciliationPayload
        : {};
      const status = String(payload.status || "").trim().toLowerCase();
      return Boolean(status && status !== "not_loaded") || Array.isArray(payload.rows);
    }

    function renderCompletedReconciliationHint(payload, rows) {
      const rowList = Array.isArray(rows) ? rows : [];
      const missingRows = completedMissingRows(rowList);
      const currentRows = completedCurrentRows(rowList);
      const missingCount = Array.isArray(missingRows) ? missingRows.length : 0;
      const reviewCount = completedReviewCount(payload, Array.isArray(currentRows) ? currentRows : []);
      const loaded = completedPublishReconciliationLoaded();
      if ((missingCount > 0 || reviewCount > 0) && !loaded) {
        setText("completed-reconciliation-hint", [
          "Backend publish reconciliation: not loaded.",
          `Output risk: ${completedRiskStatusLine(payload, rowList)}.`,
          "Safe next step: use Advanced -> Refresh Backend Reconciliation before rerun, cleanup, drain, deletion, or library decisions.",
          "Boundary: this hint is read-only and does not refresh, repair, publish, drain, rerun, rewrite manifests, or touch media.",
        ].join("\n"));
        return;
      }
      if (loaded) {
        const status = state.lastPublishReconciliationPayload?.status || "loaded";
        setText("completed-reconciliation-hint", [
          `Backend publish reconciliation: ${status}.`,
          "Use Advanced for Completed/Pending/drain-summary proof details before rerun, cleanup, or drain decisions.",
        ].join("\n"));
        return;
      }
      setText("completed-reconciliation-hint", [
        "Backend publish reconciliation: not loaded.",
        "No Output blockers are visible in the loaded Completed rows. Use Advanced when final placement or Pending Publish proof matters.",
      ].join("\n"));
    }

    function resetCompletedFilters() {
      const filter = byId("completed-filter");
      const status = byId("completed-status-filter");
      const investigation = byId("completed-investigation-filter");
      const library = byId("completed-library-filter");
      if (filter) filter.value = "";
      if (status) status.value = "all";
      if (investigation) investigation.value = "all";
      if (library) library.value = "all";
      renderCompletedRows();
      setText("completed-open-status", "Current Output Status filters cleared. Backend manifest, rerun, cleanup, and reconcile scopes are unchanged.");
    }

    function resetCompletedHistoryFilters() {
      const filter = byId("completed-history-filter");
      const status = byId("completed-history-status-filter");
      const investigation = byId("completed-history-investigation-filter");
      if (filter) filter.value = "";
      if (status) status.value = "all";
      if (investigation) investigation.value = "all";
      renderCompletedRows();
      setText("completed-open-status", "Completed History filters cleared. Backend manifest, rerun, cleanup, and reconcile scopes are unchanged.");
    }

    return {
      completedDisplayRowStatus,
      completedFilteredRows,
      completedLibraryFilterLabel,
      completedLibraryMatchesFilter,
      completedReviewCount,
      completedRiskStatusLine,
      completedRowsStatusLine,
      completedPublishReconciliationLoaded,
      renderCompletedReconciliationHint,
      resetCompletedFilters,
      resetCompletedHistoryFilters,
      syncCompletedLibraryFilterOptions,
    };
  }

  window.__completedViewFiltersModule = {
    createCompletedFiltersModule,
  };
})();

// completed/promotionCommands.js
// Split child of completedView.js. Delegates final-library promotion commands to backend routes.
/* eslint-disable max-lines-per-function -- moved promotion command logic during the completed-view split without behavior changes. */

(function () {
  "use strict";

  function noop() {}

  function normalizeDeps(deps = {}) {
    return {
      apiPost: typeof deps.apiPost === "function" ? deps.apiPost : async function () { throw new Error("apiPost is not available."); },
      appendCells: typeof deps.appendCells === "function" ? deps.appendCells : noop,
      appendCommandResult: typeof deps.appendCommandResult === "function" ? deps.appendCommandResult : noop,
      byId: typeof deps.byId === "function" ? deps.byId : function () { return null; },
      clearRows: typeof deps.clearRows === "function" ? deps.clearRows : noop,
      getSelectedCompletedRow: typeof deps.getSelectedCompletedRow === "function" ? deps.getSelectedCompletedRow : function () { return null; },
      refreshAll: typeof deps.refreshAll === "function" ? deps.refreshAll : null,
      refreshCurrentOutputStatus: typeof deps.refreshCurrentOutputStatus === "function" ? deps.refreshCurrentOutputStatus : null,
      renderCompletedRows: typeof deps.renderCompletedRows === "function" ? deps.renderCompletedRows : noop,
      selectCompletedRow: typeof deps.selectCompletedRow === "function" ? deps.selectCompletedRow : noop,
      setCellStatusChip: typeof deps.setCellStatusChip === "function" ? deps.setCellStatusChip : null,
      setText: typeof deps.setText === "function" ? deps.setText : noop,
      state: deps.state && typeof deps.state === "object" ? deps.state : {},
    };
  }

  function createCompletedPromotionCommandsModule(deps = {}) {
    const ctx = normalizeDeps(deps);
    const apiPost = ctx.apiPost;
    let commandInFlight = false;

    function finalLibraryPromotionItemsByKey(status = ctx.state.lastFinalLibraryPromotionStatus) {
      const payload = status && typeof status === "object" ? status : {};
      const items = Array.isArray(payload.items) ? payload.items : Array.isArray(payload.item_rows) ? payload.item_rows : [];
      const byKey = {};
      items.forEach((item) => {
        if (item?.row_key) byKey[item.row_key] = item;
      });
      return byKey;
    }

    function mergeFinalLibraryPromotionRows(rows, status = ctx.state.lastFinalLibraryPromotionStatus) {
      const byKey = finalLibraryPromotionItemsByKey(status);
      return (Array.isArray(rows) ? rows : []).map((row) => {
        const item = byKey[row?.row_key || ""];
        return item ? { ...row, ...item } : row;
      });
    }

    function finalLibraryPromotionStatusText(item = {}) {
      if (item.promoted_cleaned) return "✓ Promoted + cleaned";
      if (item.promoted) return "✓ Promoted";
      if (item.promoting) return "Promoting";
      if (item.paused) return "Paused";
      if (item.promotion_failed) return "Failed";
      if (item.ready_for_promotion) return "✓ Ready";
      if (item.no_destination_rule) return "No Destination Rule";
      if (item.destination_offline) return "Destination Offline";
      return item.final_library_promotion_status_label || "";
    }

    function finalLibraryPromotionChipState(item = {}) {
      if (item.promoted || item.promoted_cleaned) return "success";
      if (item.ready_for_promotion || item.promoting) return "ready";
      if (item.paused || item.destination_offline || item.no_destination_rule) return "warning";
      if (item.promotion_failed) return "error";
      return "unknown";
    }

    function finalLibraryPromotionActiveRun(status = ctx.state.lastFinalLibraryPromotionStatus) {
      const active = status?.active_run && typeof status.active_run === "object" ? status.active_run : {};
      return active?.run_id ? active : {};
    }

    function finalLibraryPromotionRunActive(status = ctx.state.lastFinalLibraryPromotionStatus) {
      const active = finalLibraryPromotionActiveRun(status);
      const state = String(active.status || "").toLowerCase();
      return Boolean(active.run_id && ["running", "pausing", "paused"].includes(state));
    }

    function finalLibraryPromotionActionState(item = {}) {
      const enabled = Boolean(ctx.state.lastFinalLibraryPromotionStatus?.enabled);
      if (!item) return { available: false, reason: "Select a completed output first." };
      if (commandInFlight) return { available: false, reason: "A promotion command is already in progress." };
      if (!enabled) return { available: false, reason: "Final Library Promotion is disabled in Settings." };
      if (finalLibraryPromotionRunActive(ctx.state.lastFinalLibraryPromotionStatus)) return { available: false, reason: "A final-library promotion run is already active." };
      if (item.promoted || item.promoted_cleaned) return { available: false, reason: "This output has already been promoted." };
      if (item.output_exists === false) return { available: false, reason: "The reviewed output is not present at the promotion source location." };
      if (item.no_destination_rule) return { available: false, reason: "No final-library destination rule is configured for this output." };
      if (item.destination_offline) return { available: false, reason: "The configured final-library destination is offline." };
      if (!item.final_library_destination_path) return { available: false, reason: "No final-library destination path is configured for this output." };
      if (!item.ready_for_promotion) return { available: false, reason: "This output is not currently marked ready for final-library promotion." };
      if (!item.row_key) return { available: false, reason: "This completed output has no backend row key." };
      return { available: true, reason: "Promote this reviewed output to the final library." };
    }

    function finalLibraryPromotionFlagLines(status = ctx.state.lastFinalLibraryPromotionStatus) {
      const payload = status && typeof status === "object" ? status : {};
      return [
        `Overwrite existing final files: ${payload.overwrite_existing ? "yes - destructive" : "no"}`,
        `Cleanup after verified promotion: ${payload.cleanup_after_verified ? "yes" : "no"}`,
        "Backend owns destination selection and file movement.",
      ];
    }

    function finalLibraryPromotionConfirmMessage(rowCount, status = ctx.state.lastFinalLibraryPromotionStatus) {
      const count = Number(rowCount || 0);
      const heading = count === 1
        ? "Promote this reviewed output to the final library?"
        : `Promote ${count || "all eligible"} reviewed outputs to the final library?`;
      const reviewed = count === 1
        ? "This means you have reviewed the output and are ready for backend final-library promotion."
        : "This means you have reviewed the outputs and are ready for backend final-library promotion.";
      const lines = [
        heading,
        "",
        reviewed,
        ...finalLibraryPromotionFlagLines(status),
      ];
      return lines.join("\n");
    }

    function shouldConfirmFinalLibraryPromotion(rowCount, status = ctx.state.lastFinalLibraryPromotionStatus) {
      if (typeof window.confirm !== "function") return true;
      return window.confirm(finalLibraryPromotionConfirmMessage(rowCount, status));
    }

    function createCompletedPromotionButton(item = {}) {
      const action = finalLibraryPromotionActionState(item);
      if (!action.available) return null;
      const button = document.createElement("button");
      button.type = "button";
      button.className = "secondary-button completed-row-promotion-button";
      button.textContent = "Promote Reviewed Output";
      button.title = "Promote this reviewed output to the final library after confirmation.";
      button.dataset.completedPromoteRowKey = item.row_key || "";
      button.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        ctx.selectCompletedRow(item);
        requestSelectedFinalLibraryPromotion(item);
      });
      return button;
    }

    function appendCompletedPromotionCellAction(cell, item = {}) {
      if (!cell) return;
      const button = createCompletedPromotionButton(item);
      if (!button) return;
      cell.classList.add("completed-promotion-cell");
      cell.appendChild(button);
    }

    function renderCompletedPromotionActions(item = ctx.getSelectedCompletedRow()) {
      const action = finalLibraryPromotionActionState(item);
      document.querySelectorAll("[data-completed-promote-selected]").forEach((button) => {
        button.disabled = !action.available;
        button.setAttribute("aria-disabled", String(!action.available));
        button.textContent = "Promote Selected Reviewed Output";
        button.title = action.reason;
      });
    }

    function renderFinalLibraryPromotion(status = {}) {
      const payload = status && typeof status === "object" ? status : {};
      ctx.state.lastFinalLibraryPromotionStatus = payload;
      if (Array.isArray(ctx.state.lastCompletedRows) && ctx.state.lastCompletedRows.length) {
        ctx.state.lastCompletedRows = mergeFinalLibraryPromotionRows(ctx.state.lastCompletedRows, payload);
      }
      const counts = payload.counts && typeof payload.counts === "object" ? payload.counts : {};
      const active = finalLibraryPromotionActiveRun(payload);
      const activeStatus = String(active.status || "").toLowerCase();
      const enabled = Boolean(payload.enabled);
      const eligible = Number(counts.eligible || 0);
      const warnings = Array.isArray(payload.warnings) ? payload.warnings.filter(Boolean) : [];
      const statusText = active.run_id
        ? `${active.status || "active"} / ${Number(active.completed_count || 0)} of ${Number(active.eligible_count || eligible || 0)}`
        : enabled
          ? `${eligible} ready`
          : "Disabled";
      ctx.setText("final-library-promotion-status", statusText);
      ctx.setText("final-library-promotion-summary", [
        `Enabled: ${enabled ? "yes" : "no"}`,
        `Verification: ${payload.verification_mode || "cautious"}`,
        `Cleanup after verified: ${payload.cleanup_after_verified ? "yes" : "no"}`,
        `Overwrite existing: ${payload.overwrite_existing ? "yes - destructive" : "no"}`,
        `Rows: ${Number(counts.total || 0)} total; ${eligible} ready; ${Number(counts.no_destination_rule || 0)} no rule; ${Number(counts.destination_offline || 0)} offline; ${Number(counts.promoted || 0)} promoted; ${Number(counts.promoted_cleaned || 0)} promoted + cleaned`,
        active.run_id ? `Active run: ${active.run_id}; status=${active.status || ""}; pause=${active.pause_state || ""}; consecutive failures=${Number(active.consecutive_failures || 0)}` : "Active run: none",
        active.stop_reason ? `Stop reason: ${active.stop_reason}` : "",
        payload.publish_root ? `Publish root: ${payload.publish_root}` : "",
        payload.evidence_root ? `Evidence: ${payload.evidence_root}` : "",
        ...warnings,
      ].filter(Boolean).join("\n"));

      const promoteButton = ctx.byId("final-library-promote-button");
      const pauseButton = ctx.byId("final-library-pause-button");
      const resumeButton = ctx.byId("final-library-resume-button");
      if (promoteButton) {
        promoteButton.disabled = commandInFlight || !enabled || finalLibraryPromotionRunActive(payload) || eligible <= 0;
        promoteButton.title = promoteButton.disabled
          ? (enabled ? "No eligible reviewed files are ready for final-library promotion, or a promotion run is active." : "Final Library Promotion is disabled in Settings.")
          : `Promote ${eligible} reviewed file${eligible === 1 ? "" : "s"} to final-library destinations after confirmation.`;
      }
      if (pauseButton) pauseButton.disabled = commandInFlight || !(active.run_id && ["running", "pausing"].includes(activeStatus));
      if (resumeButton) resumeButton.disabled = commandInFlight || !(active.run_id && activeStatus === "paused");

      const tbody = ctx.byId("final-library-promotion-rows");
      const items = Array.isArray(payload.items) ? payload.items : Array.isArray(payload.item_rows) ? payload.item_rows : [];
      if (!items.length) {
        ctx.clearRows(tbody, 3, "No final library promotion rows loaded.");
      } else {
        tbody.replaceChildren();
        items.slice(0, 40).forEach((item) => {
          const tr = document.createElement("tr");
          ctx.appendCells(tr, [
            finalLibraryPromotionStatusText(item),
            item.lookup_title || item.output_file || "",
            item.final_library_destination_path || "",
          ]);
          const statusCell = tr.querySelector("td");
          if (ctx.setCellStatusChip) {
            ctx.setCellStatusChip(statusCell, finalLibraryPromotionStatusText(item), finalLibraryPromotionChipState(item));
          }
          tbody.appendChild(tr);
        });
      }
      renderCompletedPromotionActions(ctx.getSelectedCompletedRow());
      window.mediaPipelineAppHome?.renderHomePromotionEntry?.(payload);
      ctx.renderCompletedRows();
    }

    function currentFinalLibraryPromotionRunId() {
      return String(finalLibraryPromotionActiveRun(ctx.state.lastFinalLibraryPromotionStatus).run_id || "");
    }

    function setFinalLibraryPromotionCommandBusy(isBusy) {
      commandInFlight = Boolean(isBusy);
      renderFinalLibraryPromotion(ctx.state.lastFinalLibraryPromotionStatus);
    }

    async function requestFinalLibraryPromotion(rowKeys = []) {
      if (commandInFlight) return;
      const selectedRowKeys = (Array.isArray(rowKeys) ? rowKeys : [rowKeys])
        .map((value) => String(value || "").trim())
        .filter(Boolean);
      if (!shouldConfirmFinalLibraryPromotion(selectedRowKeys.length || Number(ctx.state.lastFinalLibraryPromotionStatus?.counts?.eligible || 0), ctx.state.lastFinalLibraryPromotionStatus)) return;
      setFinalLibraryPromotionCommandBusy(true);
      ctx.setText("final-library-promotion-status", "Starting");
      try {
        const request = { confirm_promote: true };
        if (selectedRowKeys.length) request.row_keys = selectedRowKeys;
        const result = await apiPost("/api/final-library-promotion/promote-queue", request);
        ctx.appendCommandResult(result);
        ctx.setText("final-library-promotion-status", result.ok ? "Started" : "Start failed");
        if (result?.data && typeof result.data === "object") {
          renderFinalLibraryPromotion({ ...ctx.state.lastFinalLibraryPromotionStatus, active_run: result.data });
        }
        if (result?.ok) {
          if (ctx.refreshCurrentOutputStatus) {
            await ctx.refreshCurrentOutputStatus();
          } else if (ctx.refreshAll) {
            await ctx.refreshAll();
          }
        }
      } catch (error) {
        const message = error?.message || String(error);
        ctx.appendCommandResult({
          command: "final_library.promote_queue",
          ok: false,
          message,
          severity: "error",
        });
        ctx.setText("final-library-promotion-status", `Start failed: ${message}`);
      } finally {
        setFinalLibraryPromotionCommandBusy(false);
      }
    }

    async function requestSelectedFinalLibraryPromotion(item = ctx.getSelectedCompletedRow()) {
      const row = item || ctx.getSelectedCompletedRow();
      const action = finalLibraryPromotionActionState(row);
      if (!action.available) {
        ctx.setText("completed-open-status", action.reason);
        renderCompletedPromotionActions(row || null);
        return;
      }
      ctx.setText("completed-open-status", "Promotion request will be sent after confirmation. The backend owns destination selection and file movement.");
      await requestFinalLibraryPromotion([row.row_key]);
    }

    async function requestFinalLibraryPromotionPause() {
      if (commandInFlight) return;
      const runId = currentFinalLibraryPromotionRunId();
      if (!runId) {
        ctx.setText("final-library-promotion-status", "No active promotion run to pause.");
        return;
      }
      setFinalLibraryPromotionCommandBusy(true);
      try {
        const result = await apiPost("/api/final-library-promotion/pause", { run_id: runId });
        ctx.appendCommandResult(result);
        if (result?.data && typeof result.data === "object") {
          renderFinalLibraryPromotion({ ...ctx.state.lastFinalLibraryPromotionStatus, active_run: result.data });
        }
      } catch (error) {
        const message = error?.message || String(error);
        ctx.appendCommandResult({
          command: "final_library.pause",
          ok: false,
          message,
          severity: "error",
        });
        ctx.setText("final-library-promotion-status", `Pause failed: ${message}`);
      } finally {
        setFinalLibraryPromotionCommandBusy(false);
      }
    }

    async function requestFinalLibraryPromotionResume() {
      if (commandInFlight) return;
      const runId = currentFinalLibraryPromotionRunId();
      if (!runId) {
        ctx.setText("final-library-promotion-status", "No paused promotion run to resume.");
        return;
      }
      setFinalLibraryPromotionCommandBusy(true);
      try {
        const result = await apiPost("/api/final-library-promotion/resume", { run_id: runId });
        ctx.appendCommandResult(result);
        if (result?.data && typeof result.data === "object") {
          renderFinalLibraryPromotion({ ...ctx.state.lastFinalLibraryPromotionStatus, active_run: result.data });
        }
      } catch (error) {
        const message = error?.message || String(error);
        ctx.appendCommandResult({
          command: "final_library.resume",
          ok: false,
          message,
          severity: "error",
        });
        ctx.setText("final-library-promotion-status", `Resume failed: ${message}`);
      } finally {
        setFinalLibraryPromotionCommandBusy(false);
      }
    }

    return {
      appendCompletedPromotionCellAction,
      currentFinalLibraryPromotionRunId,
      finalLibraryPromotionActionState,
      finalLibraryPromotionChipState,
      finalLibraryPromotionStatusText,
      finalLibraryPromotionRunActive,
      finalLibraryPromotionItemsByKey,
      mergeFinalLibraryPromotionRows,
      renderCompletedPromotionActions,
      renderFinalLibraryPromotion,
      requestFinalLibraryPromotion,
      requestFinalLibraryPromotionPause,
      requestFinalLibraryPromotionResume,
      requestSelectedFinalLibraryPromotion,
    };
  }

  window.__completedViewPromotionCommandsModule = {
    createCompletedPromotionCommandsModule,
  };
})();

// completed/review/integrity.js
// Split child of completedView.review.js. Owns completed integrity status and evidence lines.

(function () {
  "use strict";

  function noop() {}

  function createCompletedReviewIntegrityModule(deps = {}) {
    const completedFreshnessLine = typeof deps.completedFreshnessLine === "function" ? deps.completedFreshnessLine : () => "";
    const completedFormatCounts = typeof deps.completedFormatCounts === "function" ? deps.completedFormatCounts : () => "none";
    const completedManifestIsAged = typeof deps.completedManifestIsAged === "function" ? deps.completedManifestIsAged : () => false;

    function completedRowHasIntegrityIssue(row) {
      const health = String(row?.output_health || "").trim().toLowerCase();
      return Boolean(
        row?.error ||
        row?.output_exists === false ||
        (health && !["ok", "present", "healthy"].includes(health))
      );
    }

    function completedIntegrityStatus(completed, rows) {
      const rowList = Array.isArray(rows) ? rows : [];
      if (completed?.error) return "Unavailable";
      if (!rowList.length) return "No history";
      if (Number(completed?.size_growth_over_5_count || 0) > 0) return "Review growth";
      if (Number(completed?.missing_output_count || 0) > 0 || rowList.some(completedRowHasIntegrityIssue)) return "Review needed";
      const warnings = Array.isArray(completed?.warnings) ? completed.warnings.filter(Boolean) : [];
      if (warnings.length) return "Warnings";
      if (completedManifestIsAged(completed)) return "History aged";
      return "Healthy";
    }

    function completedIntegrityLines(completed, rows) {
      const payload = completed || {};
      const rowList = Array.isArray(rows) ? rows : [];
      const warnings = Array.isArray(payload.warnings) ? payload.warnings.filter(Boolean) : [];
      const issueRows = rowList.filter(completedRowHasIntegrityIssue);
      const audioDecisionTotal = rowList.reduce((total, row) => total + Number(row.audio_decision_count || 0), 0);
      const subtitleDecisionTotal = rowList.reduce((total, row) => total + Number(row.subtitle_decision_count || 0), 0);
      if (payload.error) {
        return [
          "Status: unavailable",
          `Error: ${payload.error}`,
          "Next step: open Diagnostics > Completed Manifest and Run Logs before trusting completed history.",
        ];
      }
      const lines = [
        `Manifest: ${payload.source || "not reported"}`,
        completedFreshnessLine("Manifest age", payload.manifest_age_text, payload.manifest_freshness_status, payload.manifest_mtime_utc),
        `Rows: ${payload.count || rowList.length || 0}`,
        `Encode/remux: ${payload.encode_count || 0} / ${payload.remux_count || 0}`,
        `Missing outputs: ${payload.missing_output_count || 0}`,
        `Size growth rows: ${payload.size_growth_count || 0}`,
        `Rows over +5% output growth: ${payload.size_growth_over_5_count || 0}`,
        `Rows without source/output size comparison: ${payload.size_unknown_count || 0}`,
        `Rows needing review: ${issueRows.length}`,
        `Operator statuses: ${completedFormatCounts(payload.operator_status_counts)}`,
        `Operator severities: ${completedFormatCounts(payload.operator_severity_counts)}`,
        `Backend open targets: ${completedFormatCounts(payload.available_open_target_counts)}`,
        `Runtime outcome matches: ${payload.runtime_outcome_match_count || 0}`,
        `Audio/subtitle decisions: ${audioDecisionTotal} / ${subtitleDecisionTotal}`,
        payload.total_output_size_text ? `Loaded output size: ${payload.total_output_size_text}` : "",
      ].filter(Boolean);
      if (warnings.length) {
        lines.push("", "Warning(s):");
        warnings.slice(0, 5).forEach((warning) => lines.push(`- ${warning}`));
      }
      lines.push("");
      if (!rowList.length) {
        lines.push("Next step: no completed-history rows are loaded. This is normal before the first successful job; otherwise open the completed manifest from Diagnostics.");
      } else if (Number(payload.size_growth_over_5_count || 0) > 0) {
        lines.push("Next step: inspect size-growth rows before using rerun results as proof of success. Growth may be expected for compatibility, but large growth needs operator review.");
      } else if (issueRows.length || Number(payload.missing_output_count || 0) > 0) {
        lines.push("Next step: inspect rows needing review before rerunning media. Use backend-selected open buttons for output folders, sidecars, and source folders.");
      } else if (warnings.length) {
        lines.push("Next step: review warnings, but loaded completed rows do not currently report missing outputs.");
      } else if (completedManifestIsAged(payload)) {
        lines.push("Next step: completed history is older than the freshness threshold. This can be normal when no jobs have run; if it conflicts with disk contents, open Completed Manifest and Run Logs before rerun.");
      } else {
        lines.push("Next step: completed outputs look healthy in the loaded manifest preview.");
      }
      lines.push("Mutation guardrail: repair, reconcile, and rerun actions must remain backend-owned commands.");
      return lines;
    }

    return {
      completedRowHasIntegrityIssue,
      completedIntegrityStatus,
      completedIntegrityLines,
    };
  }

  window.__completedViewReviewIntegrityModule = {
    createCompletedReviewIntegrityModule,
  };
})();

// completed/review/reviewRows.js
// Split child of completedView.review.js. Owns completed review row reasons, board lines, digest status, and table status.

(function () {
  "use strict";

  function noopRows() { return []; }

  function createCompletedReviewRowsModule(deps = {}) {
    const completedFormatCounts = typeof deps.completedFormatCounts === "function" ? deps.completedFormatCounts : () => "none";
    const completedManifestIsAged = typeof deps.completedManifestIsAged === "function" ? deps.completedManifestIsAged : () => false;
    const completedWorkflowStatus = typeof deps.completedWorkflowStatus === "function" ? deps.completedWorkflowStatus : () => "Unknown";
    const completedHasSmallHealthySizeDelta = typeof deps.completedHasSmallHealthySizeDelta === "function" ? deps.completedHasSmallHealthySizeDelta : () => false;
    const completedPrimaryConcernIsBenign = typeof deps.completedPrimaryConcernIsBenign === "function" ? deps.completedPrimaryConcernIsBenign : () => false;
    const completedReviewFlagIsBenign = typeof deps.completedReviewFlagIsBenign === "function" ? deps.completedReviewFlagIsBenign : () => false;
    const completedRowHasIntegrityIssue = typeof deps.completedRowHasIntegrityIssue === "function" ? deps.completedRowHasIntegrityIssue : () => false;
    const completedRowHasSmallHealthySizeGrowth = typeof deps.completedRowHasSmallHealthySizeGrowth === "function" ? deps.completedRowHasSmallHealthySizeGrowth : () => false;
    const completedRowLooksHealthy = typeof deps.completedRowLooksHealthy === "function" ? deps.completedRowLooksHealthy : () => false;
    const completedRowHasBenignAlreadyProcessedOutcome = typeof deps.completedRowHasBenignAlreadyProcessedOutcome === "function" ? deps.completedRowHasBenignAlreadyProcessedOutcome : () => false;

    function completedReviewRowReasons(row) {
      const reasons = [];
      const severity = String(row?.operator_severity || "").toLowerCase();
      const consistency = String(row?.consistency_status || "").toLowerCase();
      const runtimeStatus = String(row?.runtime_outcome_status || "").toLowerCase();
      const runtimeFreshness = String(row?.runtime_outcome_freshness_status || "").toLowerCase();
      const reviewFlags = Array.isArray(row?.review_flags) ? row.review_flags.filter((flag) => !completedReviewFlagIsBenign(flag, row)) : [];
      if (severity === "error") reasons.push("backend error severity");
      if (severity === "warning" && !completedRowHasSmallHealthySizeGrowth(row)) reasons.push("backend warning severity");
      if (row?.output_exists === false) reasons.push("missing output");
      if (row?.size_growth_over_5) reasons.push("output grew more than 5%");
      if (consistency && !["ok", "healthy", "consistent", "consistent-looking"].includes(consistency)) reasons.push(`consistency: ${row.consistency_status}`);
      if (row?.sidecar_exists === false) reasons.push("missing sidecar");
      if (Array.isArray(row?.consistency_issues) && row.consistency_issues.length) reasons.push(`consistency issues: ${row.consistency_issues.slice(0, 2).join(", ")}`);
      if (runtimeFreshness === "fresh" && ["failed", "error", "skipped", "stopped"].some((value) => runtimeStatus.includes(value))) {
        reasons.push(`fresh runtime outcome: ${row.runtime_outcome_status}`);
      }
      if (reviewFlags.length) reasons.push(`review flags: ${reviewFlags.join(", ")}`);
      if (String(row?.operator_trust_state || "").toLowerCase().includes("review") && !completedRowLooksHealthy(row)) reasons.push(`trust state: ${row.operator_trust_state}`);
      if (row?.primary_concern && !completedPrimaryConcernIsBenign(row)) reasons.push(`primary concern: ${row.primary_concern}`);
      return reasons.filter(Boolean);
    }

    function completedReviewRows(completed, rows) {
      const rowList = Array.isArray(rows) ? rows : [];
      return rowList
        .map((row, index) => ({ row, index, reasons: completedReviewRowReasons(row) }))
        .filter((entry) => entry.reasons.length)
        .sort((a, b) => {
          const rank = (entry) => String(entry.row?.operator_severity || "").toLowerCase() === "error" ? 0
            : entry.row?.output_exists === false ? 1
              : entry.row?.size_growth_over_5 ? 2
                : String(entry.row?.operator_severity || "").toLowerCase() === "warning" ? 3
                  : 4;
          return rank(a) - rank(b) || a.index - b.index;
        });
    }

    function completedReviewStatus(completed, rows) {
      const payload = completed || {};
      const rowList = Array.isArray(rows) ? rows : [];
      if (payload.error) return "Diagnostics first";
      const reviewRows = completedReviewRows(payload, rowList);
      if (reviewRows.length) return `${reviewRows.length} row${reviewRows.length === 1 ? "" : "s"} need review`;
      if (!rowList.length) return "No history";
      if (completedManifestIsAged(payload)) return "History aged";
      return "No flagged rows";
    }

    function completedReviewBoardLines(completed, rows) {
      const payload = completed || {};
      const rowList = Array.isArray(rows) ? rows : [];
      const reviewRows = completedReviewRows(payload, rowList);
      const lines = [
        "Operator review board: Completed",
        `Page status: ${completedWorkflowStatus(payload, rowList)}`,
        `Rows loaded: ${payload.count || rowList.length || 0}`,
        `Flagged rows: ${reviewRows.length}`,
        `Backend trust states: ${completedFormatCounts(payload.operator_trust_state_counts)}`,
        `Operator severities: ${completedFormatCounts(payload.operator_severity_counts)}`,
        `Runtime freshness: ${completedFormatCounts(payload.runtime_outcome_freshness_counts)}`,
        `Size growth over +5%: ${payload.size_growth_over_5_count || 0}`,
      ];
      lines.push("");
      if (payload.error) {
        lines.push("First action: open Diagnostics > Completed Manifest, Run Logs, and Last Stderr. Do not use completed history for rerun/cleanup decisions while unavailable.");
      } else if (reviewRows.length) {
        lines.push("First rows to inspect:");
        reviewRows.slice(0, 6).forEach(({ row, reasons }, index) => {
          const label = row.lookup_title || row.output_file || row.output_path || `row ${index + 1}`;
          const action = row.safe_next_action || row.operator_guidance || "select the row and use Completed Diagnostics Cross-Links before rerun or cleanup.";
          lines.push(`- ${label}: ${reasons.slice(0, 3).join("; ")}. Safe action: ${action}`);
        });
        if (reviewRows.length > 6) lines.push(`- ${reviewRows.length - 6} more flagged row(s) not shown.`);
      } else if (!rowList.length) {
        lines.push("First action: no completed rows are loaded. This is normal before first success; otherwise inspect Completed Manifest from Diagnostics.");
      } else if (completedManifestIsAged(payload)) {
        lines.push("First action: completed rows are not locally flagged, but manifest history is aged. Compare disk state with Completed Manifest and Run Logs before cleanup or rerun.");
      } else {
        lines.push("First action: no completed rows are locally flagged. Use Queue for new work and Pending Publish before rerunning missing-output cases.");
      }
      lines.push("Mutation guardrail: this board is read-only; repair, reconcile, rerun, cleanup, and file deletion remain backend-owned.");
      return lines;
    }

    function completedReviewDigestStatus(entry) {
      const row = entry?.row || {};
      const severity = String(row.operator_severity || "").toLowerCase();
      if (severity === "error" || row.output_exists === false || String(row.output_health || "").toLowerCase().includes("missing")) return "blocked";
      if (severity === "warning" || row.size_growth_over_5 || entry?.reasons?.length) return "warning";
      return "match";
    }

    function completedReviewDigestAction(row) {
      return row?.safe_next_action
        || row?.operator_guidance
        || "Select this row, compare Completed detail with Diagnostics Cross-Links, then leave repair/rerun/reconcile decisions to backend-owned workflows.";
    }

    function completedTableRowStatus(item) {
      const backendState = typeof backendRowStatusState === "function" ? backendRowStatusState(item) : "";
      const benignAlreadyProcessed = completedRowHasBenignAlreadyProcessedOutcome(item);
      if (backendState === "changed" && completedHasSmallHealthySizeDelta(item)) return "match";
      if (completedRowLooksHealthy(item) && ["", "normal", "warning", "changed", "unknown"].includes(backendState)) return "match";
      if (benignAlreadyProcessed && ["", "normal", "warning", "changed", "unknown"].includes(backendState)) return "match";
      if (backendState) return backendState;
      const severity = String(item?.operator_severity || "").toLowerCase();
      if (severity === "error" || item?.output_exists === false || completedRowHasIntegrityIssue(item)) return "blocked";
      if (benignAlreadyProcessed) return "match";
      if (severity === "warning" || item?.size_growth_over_5 || completedReviewRowReasons(item).length) return "warning";
      return "match";
    }

    return {
      completedReviewRowReasons,
      completedReviewRows,
      completedReviewStatus,
      completedReviewBoardLines,
      completedReviewDigestStatus,
      completedReviewDigestAction,
      completedTableRowStatus,
    };
  }

  window.__completedViewReviewRowsModule = {
    createCompletedReviewRowsModule,
  };
})();

