  const auditScoreFieldIds = {
    redownload_bucket: "audit-score-redownload-bucket",
    high_issue: "audit-score-high-issue",
    rerun_bucket: "audit-score-rerun-bucket",
    medium_issue: "audit-score-medium-issue",
