  function drawerOverrideState(entry) {
    const audio = isPlainObject(entry?.audio) ? entry.audio : {};
    const subs = isPlainObject(entry?.subtitles) ? entry.subtitles : {};
    const routing = isPlainObject(entry?.routing) ? entry.routing : {};
