  function allFailureMarkerPaths() {
    const seen = new Set();
    const paths = [];
    lastFailureRows.forEach((item) => {
      failureClearMarkerPathsForRow(item).forEach((markerPath) => {
        const key = markerPath.toLowerCase();
        if (markerPath && !seen.has(key)) {
          seen.add(key);
          paths.push(markerPath);
        }
      });
