  function schedulePayloadLoaded(schedule) {
    return Boolean(
      schedule &&
      typeof schedule === "object" &&
      (
        schedule.schema_version ||
        schedule.evaluation ||
        schedule.enabled !== undefined ||
        Array.isArray(schedule.day_summaries) ||
